    optional_used: List[str] = []
    if theorem and lean_exit == 0:
        parsed, parse_error = _parse_used_axioms(lean_output, theorem)
        if parse_error:
            result.errors.append(parse_error)
        else:
            used = parsed or []
        if optional_theorem:
            optional_parsed, optional_parse_error = _parse_used_axioms(
